 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[[0]*w for _ in range(h)]
    # 8s are fixed anchors; every other color object shifts right until its rightmost cell meets the edge or an anchor.
    anchors={(r,c) for r in range(h) for c in range(w) if grid[r][c]==8}
    for r in range(h):
        for c in range(w):
            if grid[r][c]==8: out[r][c]=8
    seen=set()
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v in (0,8) or (r,c) in seen: continue
            todo=[(r,c)]; seen.add((r,c)); comp=[]
            while todo:
                y,x=todo.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
